6	export default async function (tree: Tree) {
7	  visitNotIgnoredFiles(tree, '', (path) => {
8	    const webpackConfigGlob = '**/webpack*.config*.{js,ts,mjs,cjs}';
9	    const result = picomatch(webpackConfigGlob)(path);
10	    if (!result) {
11	      return;
12	    }
13	    let webpackConfigContents = tree.read(path, 'utf-8');
14	    if (
15	      !/withModuleFederationSSR|withModuleFederation/.test(
16	        webpackConfigContents
17	      )
18	    ) {
19	      return;
20	    }
21	
22	    const WITH_MODULE_FEDERATION_SELECTOR =
23	      'CallExpression:has(Identifier[name=withModuleFederation]),CallExpression:has(Identifier[name=withModuleFederationForSSR])';
24	    const EXISTING_MF_OVERRIDES_SELECTOR = 'ObjectLiteralExpression';
25	
26	    const sourceFile = ast(webpackConfigContents);
27	    const withModuleFederationNodes = query(
28	      sourceFile,
29	      WITH_MODULE_FEDERATION_SELECTOR
30	    );
31	    if (!withModuleFederationNodes.length) {
32	      return;
33	    }
34	
35	    const withModuleFederationNode = withModuleFederationNodes[0];
36	    const existingOverridesNodes = query(
37	      withModuleFederationNode,
38	      EXISTING_MF_OVERRIDES_SELECTOR
39	    );
40	    if (!existingOverridesNodes.length) {
41	      // doesn't exist, add it
42	      webpackConfigContents = `${webpackConfigContents.slice(
43	        0,
44	        withModuleFederationNode.getEnd() - 1
45	      )},${JSON.stringify({ dts: false })}${webpackConfigContents.slice(
46	        withModuleFederationNode.getEnd() - 1
47	      )}`;
48	    } else {
49	      let existingOverrideNode;
50	      for (const node of existingOverridesNodes) {
51	        if (!existingOverrideNode) {
52	          existingOverrideNode = node;
53	        }
54	        if (existingOverrideNode.getText().includes(node.getText())) {
55	          continue;
56	        }
57	        existingOverrideNode = node;
58	      }
59	      const DTS_PROPERTY_SELECTOR = 'PropertyAssignment > Identifier[name=dts]';
60	      const dtsPropertyNode = query(
61	        existingOverrideNode,
62	        DTS_PROPERTY_SELECTOR
63	      );
64	      if (dtsPropertyNode.length) {
65	        // dts already exists, do nothing
66	        return;
67	      }
68	
69	      const newOverrides = `{ dts: false, ${existingOverrideNode
70	        .getText()
71	        .slice(1)}`;
72	      webpackConfigContents = `${webpackConfigContents.slice(
73	        0,
74	        existingOverrideNode.getStart()
75	      )}${newOverrides}${webpackConfigContents.slice(
76	        existingOverrideNode.getEnd()
77	      )}`;
78	    }
79	    tree.write(path, webpackConfigContents);
80	  });
81	
82	  await formatFiles(tree);
