const COLLECTION = '@nx/angular';
const OLD_GENERATOR = 'ngrx';
const ROOT_STORE_GENERATOR = 'ngrx-root-store';
const FEATURE_STORE_GENERATOR = 'ngrx-feature-store';

const OLD_FLAT_KEY = `${COLLECTION}:${OLD_GENERATOR}`;

// Options that are carried over to each new generator.
const ROOT_STORE_OPTIONS = ['facade', 'minimal', 'directory'] as const;
const FEATURE_STORE_OPTIONS = ['facade', 'barrels', 'directory'] as const;

export default async function migrateNgrxGeneratorDefaults(
  tree: Tree
): Promise<void> {
  const nxJson = readNxJson(tree);
  if (nxJson?.generators && migrateGenerators(nxJson.generators)) {
    updateNxJson(tree, nxJson);
  }

  const projects = getProjects(tree);
  for (const [name, project] of projects) {
    if (project.generators && migrateGenerators(project.generators)) {
      updateProjectConfiguration(tree, name, project);
    }
  }

  await formatFiles(tree);
}

/**
 * Redistributes the old `@nx/angular:ngrx` generator defaults (in either flat
 * or nested form) to the new `@nx/angular:ngrx-root-store` and
 * `@nx/angular:ngrx-feature-store` generators.
 *
 * Returns whether any change was made to the provided generators object.
 */
function migrateGenerators(generators: Record<string, any>): boolean {
  const flatOld = generators[OLD_FLAT_KEY];
  const nestedOld = generators[COLLECTION]?.[OLD_GENERATOR];

  if (flatOld === undefined && nestedOld === undefined) {
    return false;
  }

  // When both formats coexist, the flat format takes precedence.
  const oldOptions = { ...(nestedOld ?? {}), ...(flatOld ?? {}) };

  // When there are no flat defaults, mirror the nested output format.
  const preferNested = flatOld === undefined;

  const rootOptions = pick(oldOptions, ROOT_STORE_OPTIONS);
  const featureOptions = pick(oldOptions, FEATURE_STORE_OPTIONS);

  // The old `module` option is renamed to `parent` on the feature store. When
  // both `module` and `parent` are set, `module` takes precedence.
  if ('module' in oldOptions) {
    featureOptions.parent = oldOptions.module;
  } else if ('parent' in oldOptions) {
    featureOptions.parent = oldOptions.parent;
  }

  // Remove the old defaults regardless of their format.
  delete generators[OLD_FLAT_KEY];
  if (nestedOld !== undefined) {
    delete generators[COLLECTION][OLD_GENERATOR];
  }

  writeNewKey(generators, ROOT_STORE_GENERATOR, rootOptions, preferNested);
  writeNewKey(generators, FEATURE_STORE_GENERATOR, featureOptions, preferNested);

  // Clean up the nested collection if it was emptied by the migration.
  if (
    generators[COLLECTION] &&
    Object.keys(generators[COLLECTION]).length === 0
  ) {
    delete generators[COLLECTION];
  }

  return true;
}

function pick(
  source: Record<string, any>,
  keys: readonly string[]
): Record<string, any> {
  const result: Record<string, any> = {};
  for (const key of keys) {
    if (key in source) {
      result[key] = source[key];
    }
  }
  return result;
}

function writeNewKey(
  generators: Record<string, any>,
  generator: string,
  options: Record<string, any>,
  preferNested: boolean
): void {
  // The obsolete options may leave nothing to write; never write empty defaults.
  if (Object.keys(options).length === 0) {
    return;
  }

  const flatKey = `${COLLECTION}:${generator}`;
  const existingFlat = generators[flatKey];
  const existingNested = generators[COLLECTION]?.[generator];

  // Existing user-set values on the new keys take priority over migrated ones.
  if (existingFlat !== undefined) {
    generators[flatKey] = { ...options, ...existingFlat };
  } else if (existingNested !== undefined) {
    generators[COLLECTION][generator] = { ...options, ...existingNested };
  } else if (preferNested) {
    generators[COLLECTION] ??= {};
    generators[COLLECTION][generator] = options;
  } else {
    generators[flatKey] = options;
  }
}
